def item(w,pos,m,lv,k='',rd='',note='',tags=None,ex='',tr=''):
    return {'w':w,'k':k,'pos':pos,'m':m,'rd':rd,'alt':'','ex':ex,'tr':tr,'note':note,'lv':lv,'tags':tags or [],'img':'','fig':''}
