SEI={x['w']:x for x in json.load(open(HERE+'seiritsu.json',encoding='utf-8'))}
bun=[]
for l in open(HERE+'bungakushi.tsv',encoding='utf-8'):
    if l.startswith('#') or not l.strip(): continue
    p=(l.rstrip('\n').split('\t')+['']*8)[:8]; era,c,w,g,au,yr,mk,note=p
    g=FIX.get(w) or g
    if w=='土佐日記': note='最初の仮名の日記'
    m=[f'{era}時代（{c}世紀）の{g}'+(f'。{au}' if au else '')]
    if note: m.append(note)
    tags=[]+(['マーカー'] if mk else [])+(['チェックリスト'] if w in CHECK else [])
    it=item(w,'作品',m,ERA[era],rd=RD.get(w,''),note=('' if w in SEI else (f'成立 {yr}年' if yr else '')),tags=tags)
    if w in SEI:
        s=SEI[w]; assert s['book']==yr,(w,s['book'],yr)
        it['sei']={'y':s['y'],'conf':s['conf'],'basis':s['basis'],'caveat':s['caveat'],'book':yr}
    elif yr: raise SystemExit('seiritsu.json に成立の根拠がありません: '+w)
    bun.append(it)
